import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  CalendarIcon,
  FunnelIcon,
  ArrowDownTrayIcon,
  MagnifyingGlassIcon,
  EyeIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';
import ActivityLogDetailModal from '../components/ActivityLogDetailModal';
import apiClient from '../services/apiClient';

const ActivityLogs = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({});
  const [selectedLog, setSelectedLog] = useState(null);

  // Filter states
  const [filters, setFilters] = useState({
    action: '',
    targetType: '',
    adminEmail: '',
    startDate: '',
    endDate: '',
    page: 1,
    limit: 20
  });
  const [showFilters, setShowFilters] = useState(false);
  const [exporting, setExporting] = useState(false);

  // Action and target type options
  const actionOptions = [
    { value: '', label: 'All Actions' },
    { value: 'approve_property', label: 'Approve Property' },
    { value: 'reject_property', label: 'Reject Property' },
    { value: 'delete_property', label: 'Delete Property' },
    { value: 'bulk_approve_properties', label: 'Bulk Approve Properties' },
    { value: 'bulk_reject_properties', label: 'Bulk Reject Properties' },
    { value: 'bulk_delete_properties', label: 'Bulk Delete Properties' },
    { value: 'suspend_user', label: 'Suspend User' },
    { value: 'ban_user', label: 'Ban User' },
    { value: 'unban_user', label: 'Unban User' },
    { value: 'delete_user', label: 'Delete User' },
    { value: 'bulk_suspend_users', label: 'Bulk Suspend Users' },
    { value: 'bulk_ban_users', label: 'Bulk Ban Users' }
  ];

  const targetTypeOptions = [
    { value: '', label: 'All Types' },
    { value: 'property', label: 'Property' },
    { value: 'user', label: 'User' },
    { value: 'appointment', label: 'Appointment' }
  ];

  // Fetch activity logs
  const fetchLogs = async () => {
    try {
      setLoading(true);
      setError(null);

      const queryParams = new URLSearchParams();
      Object.entries(filters).forEach(([key, value]) => {
        if (value) queryParams.append(key, value);
      });

      const response = await apiClient.get(`/api/admin/activity-logs?${queryParams}`);
      const data = response.data;
      setLogs(data.logs || []);
      setPagination(data.pagination || {});
    } catch (err) {
      console.error('Error fetching activity logs:', err);
      setError(`Failed to load activity logs. ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Export CSV
  const handleExport = async () => {
    try {
      setExporting(true);

      const queryParams = new URLSearchParams();
      // Remove pagination for export (get all matching records)
      const exportFilters = { ...filters };
      delete exportFilters.page;
      delete exportFilters.limit;

      Object.entries(exportFilters).forEach(([key, value]) => {
        if (value) queryParams.append(key, value);
      });

      const response = await apiClient.get(`/api/admin/activity-logs/export?${queryParams}`, {
        responseType: 'blob',
      });

      // Download file
      const blob = response.data;
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `activity-logs-${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      console.error('Error exporting logs:', err);
      setError('Failed to export logs. Please try again.');
    } finally {
      setExporting(false);
    }
  };

  // Handle filter changes
  const handleFilterChange = (key, value) => {
    setFilters(prev => ({
      ...prev,
      [key]: value,
      page: 1 // Reset to first page when filtering
    }));
  };

  // Handle pagination
  const handlePageChange = (newPage) => {
    setFilters(prev => ({
      ...prev,
      page: newPage
    }));
  };

  // Clear filters
  const clearFilters = () => {
    setFilters({
      action: '',
      targetType: '',
      adminEmail: '',
      startDate: '',
      endDate: '',
      page: 1,
      limit: 20
    });
  };

  // Get action badge color
  const getActionBadgeColor = (action) => {
    if (action.includes('approve')) return 'bg-green-100 text-green-800 border-green-200';
    if (action.includes('reject')) return 'bg-red-100 text-red-800 border-red-200';
    if (action.includes('delete')) return 'bg-red-100 text-red-800 border-red-200';
    if (action.includes('suspend') || action.includes('ban')) return 'bg-orange-100 text-orange-800 border-orange-200';
    if (action.includes('unban')) return 'bg-blue-100 text-blue-800 border-blue-200';
    if (action.includes('bulk')) return 'bg-purple-100 text-purple-800 border-purple-200';
    return 'bg-gray-100 text-gray-800 border-gray-200';
  };

  // Get target type badge color
  const getTargetTypeBadgeColor = (targetType) => {
    switch (targetType) {
      case 'property': return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'user': return 'bg-green-100 text-green-800 border-green-200';
      case 'appointment': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  // Format action display name
  const formatActionName = (action) => {
    return action.split('_').map(word =>
      word.charAt(0).toUpperCase() + word.slice(1)
    ).join(' ');
  };

  // Format date
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZoneName: 'short'
    });
  };

  useEffect(() => {
    fetchLogs();
  }, [filters]);

  // Report error to parent/toast system
  useEffect(() => {
    if (error) {
      // Here we'd typically show a toast notification
      console.error('Activity Logs Error:', error);
    }
  }, [error]);

  return (
    <div className="p-6">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-[#1C1B1A]">Activity Logs</h1>
            <p className="text-gray-600 mt-1">
              Comprehensive audit trail of all administrative actions
            </p>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`px-4 py-2 rounded-lg border transition-colors duration-200 ${
                showFilters
                  ? 'bg-[#D4755B] text-white border-[#D4755B]'
                  : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
              }`}
            >
              <FunnelIcon className="w-4 h-4 inline mr-2" />
              Filters
            </button>

            <button
              onClick={handleExport}
              disabled={exporting || logs.length === 0}
              className="px-4 py-2 bg-[#D4755B] text-white rounded-lg hover:bg-[#C06549]
                       disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors duration-200"
            >
              <ArrowDownTrayIcon className="w-4 h-4 inline mr-2" />
              {exporting ? 'Exporting...' : 'Export CSV'}
            </button>
          </div>
        </div>
      </div>

      {/* Filters Panel */}
      <AnimatePresence>
        {showFilters && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="mb-6 bg-white rounded-lg border border-[#E6D5C3] p-4"
          >
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {/* Action Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Action
                </label>
                <select
                  value={filters.action}
                  onChange={(e) => handleFilterChange('action', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2
                           focus:ring-[#D4755B] focus:border-transparent"
                >
                  {actionOptions.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Target Type Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Target Type
                </label>
                <select
                  value={filters.targetType}
                  onChange={(e) => handleFilterChange('targetType', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2
                           focus:ring-[#D4755B] focus:border-transparent"
                >
                  {targetTypeOptions.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Admin Email Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Admin Email
                </label>
                <input
                  type="email"
                  value={filters.adminEmail}
                  onChange={(e) => handleFilterChange('adminEmail', e.target.value)}
                  placeholder="admin@buildestate.com"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2
                           focus:ring-[#D4755B] focus:border-transparent"
                />
              </div>

              {/* Start Date */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Start Date
                </label>
                <input
                  type="date"
                  value={filters.startDate}
                  onChange={(e) => handleFilterChange('startDate', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2
                           focus:ring-[#D4755B] focus:border-transparent"
                />
              </div>

              {/* End Date */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  End Date
                </label>
                <input
                  type="date"
                  value={filters.endDate}
                  onChange={(e) => handleFilterChange('endDate', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2
                           focus:ring-[#D4755B] focus:border-transparent"
                />
              </div>

              {/* Clear Filters */}
              <div className="flex items-end">
                <button
                  onClick={clearFilters}
                  className="w-full px-4 py-2 text-gray-700 bg-gray-100 rounded-md
                           hover:bg-gray-200 transition-colors duration-200"
                >
                  Clear Filters
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Content */}
      {loading ? (
        <div className="bg-white rounded-lg border border-[#E6D5C3] p-6">
          <div className="animate-pulse space-y-4">
            {[...Array(10)].map((_, i) => (
              <div key={i} className="flex items-center space-x-4">
                <div className="h-4 bg-[#E6D5C3] rounded w-24"></div>
                <div className="h-4 bg-[#E6D5C3] rounded w-32"></div>
                <div className="h-4 bg-[#E6D5C3] rounded w-20"></div>
                <div className="h-4 bg-[#E6D5C3] rounded w-40"></div>
                <div className="h-4 bg-[#E6D5C3] rounded w-16"></div>
              </div>
            ))}
          </div>
        </div>
      ) : error ? (
        <div className="bg-white rounded-lg border border-[#E6D5C3] p-6">
          <div className="text-center">
            <ExclamationTriangleIcon className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">Error Loading Logs</h3>
            <p className="text-gray-600 mb-4">{error}</p>
            <button
              onClick={() => fetchLogs()}
              className="px-4 py-2 bg-[#D4755B] text-white rounded-lg hover:bg-[#C06549]
                       transition-colors duration-200"
            >
              Try Again
            </button>
          </div>
        </div>
      ) : logs.length === 0 ? (
        <div className="bg-white rounded-lg border border-[#E6D5C3] p-6">
          <div className="text-center">
            <MagnifyingGlassIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No Activity Logs Found</h3>
            <p className="text-gray-600 mb-4">
              {Object.values(filters).some(v => v && v !== 1 && v !== 20)
                ? 'No logs match your current filters.'
                : 'No administrative actions have been recorded yet.'
              }
            </p>
            {Object.values(filters).some(v => v && v !== 1 && v !== 20) && (
              <button
                onClick={clearFilters}
                className="px-4 py-2 bg-[#D4755B] text-white rounded-lg hover:bg-[#C06549]
                         transition-colors duration-200"
              >
                Clear Filters
              </button>
            )}
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-lg border border-[#E6D5C3] overflow-hidden">
          {/* Table */}
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-[#FAF8F4] border-b border-[#E6D5C3]">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Timestamp
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Admin
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Action
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Target
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Details
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#E6D5C3]">
                {logs.map((log) => (
                  <tr key={log._id} className="hover:bg-[#FAF8F4] transition-colors duration-150">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {formatDate(log.createdAt)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {log.adminEmail}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full border ${getActionBadgeColor(log.action)}`}>
                        {formatActionName(log.action)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center space-x-2">
                        <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full border ${getTargetTypeBadgeColor(log.targetType)}`}>
                          {log.targetType}
                        </span>
                        {log.targetName && (
                          <span className="text-sm text-gray-600 max-w-40 truncate">
                            {log.targetName}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                      {log.metadata?.reason && (
                        <span className="max-w-40 truncate block">
                          {log.metadata.reason}
                        </span>
                      )}
                      {log.metadata?.count && (
                        <span className="text-xs text-gray-500">
                          {log.metadata.count} items
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button
                        onClick={() => setSelectedLog(log)}
                        className="text-[#D4755B] hover:text-[#C06549] font-medium"
                      >
                        <EyeIcon className="w-4 h-4 inline mr-1" />
                        View Details
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {pagination.totalPages > 1 && (
            <div className="bg-[#FAF8F4] px-6 py-3 border-t border-[#E6D5C3] flex items-center justify-between">
              <div className="text-sm text-gray-700">
                Showing {((pagination.currentPage - 1) * pagination.limit) + 1} to{' '}
                {Math.min(pagination.currentPage * pagination.limit, pagination.total)} of{' '}
                {pagination.total} results
              </div>

              <div className="flex items-center space-x-2">
                <button
                  onClick={() => handlePageChange(pagination.currentPage - 1)}
                  disabled={pagination.currentPage <= 1}
                  className="px-3 py-1 text-sm bg-white border border-gray-300 rounded-md
                           hover:bg-gray-50 disabled:bg-gray-100 disabled:cursor-not-allowed"
                >
                  Previous
                </button>

                <span className="px-3 py-1 text-sm text-gray-700">
                  Page {pagination.currentPage} of {pagination.totalPages}
                </span>

                <button
                  onClick={() => handlePageChange(pagination.currentPage + 1)}
                  disabled={pagination.currentPage >= pagination.totalPages}
                  className="px-3 py-1 text-sm bg-white border border-gray-300 rounded-md
                           hover:bg-gray-50 disabled:bg-gray-100 disabled:cursor-not-allowed"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Activity Log Detail Modal */}
      {selectedLog && (
        <ActivityLogDetailModal
          isOpen={!!selectedLog}
          log={selectedLog}
          onClose={() => setSelectedLog(null)}
        />
      )}
    </div>
  );
};

export default ActivityLogs;

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Calendar, Clock, User, Home, Check, X, Loader2,
  Filter, Search, Link as LinkIcon, Send, AlertCircle,
  ChevronDown,
} from "lucide-react";
import { toast } from "sonner";
import apiClient from "../services/apiClient";
import { cn, formatDate } from "../lib/utils";

const STATUS_CONFIG = {
  pending: { label: "Pending", className: "bg-amber-50 text-amber-700 border border-amber-200" },
  confirmed: { label: "Confirmed", className: "bg-emerald-50 text-emerald-700 border border-emerald-200" },
  cancelled: { label: "Cancelled", className: "bg-red-50 text-red-700 border border-red-200" },
};

const StatusBadge = ({ status }) => {
  const config = STATUS_CONFIG[status] || { label: status, className: "bg-gray-100 text-gray-700" };
  return (
    <span className={cn("px-2.5 py-1 rounded-full text-xs font-semibold", config.className)}>
      {config.label}
    </span>
  );
};

const Appointments = () => {
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [editingMeetingLink, setEditingMeetingLink] = useState(null);
  const [meetingLink, setMeetingLink] = useState("");
  const [updatingId, setUpdatingId] = useState(null);

  const fetchAppointments = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get('/api/appointments/all');
      if (response.data.success) {
        const valid = response.data.appointments.filter((apt) => apt.propertyId);
        setAppointments(valid);
      } else {
        toast.error(response.data.message);
      }
    } catch (error) {
      console.error("Error fetching appointments:", error);
      toast.error("Failed to fetch appointments");
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (appointmentId, newStatus) => {
    try {
      setUpdatingId(appointmentId);
      const response = await apiClient.put('/api/appointments/status', { appointmentId, status: newStatus });
      if (response.data.success) {
        toast.success(`Appointment ${newStatus} successfully`);
        fetchAppointments();
      } else {
        toast.error(response.data.message);
      }
    } catch (error) {
      console.error("Error updating appointment:", error);
      toast.error("Failed to update appointment status");
    } finally {
      setUpdatingId(null);
    }
  };

  const handleMeetingLinkUpdate = async (appointmentId) => {
    if (!meetingLink) { toast.error("Please enter a meeting link"); return; }
    try {
      const response = await apiClient.put('/api/appointments/update-meeting', { appointmentId, meetingLink });
      if (response.data.success) {
        toast.success("Meeting link sent successfully");
        setEditingMeetingLink(null);
        setMeetingLink("");
        fetchAppointments();
      } else {
        toast.error(response.data.message);
      }
    } catch (error) {
      console.error("Error updating meeting link:", error);
      toast.error("Failed to update meeting link");
    }
  };

  useEffect(() => { fetchAppointments(); }, []);

  const filteredAppointments = appointments.filter((apt) => {
    const clientName = apt.userId?.name || apt.guestInfo?.name || "";
    const clientEmail = apt.userId?.email || apt.guestInfo?.email || "";
    const matchesSearch =
      !searchTerm ||
      apt.propertyId?.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      clientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      clientEmail.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filter === "all" || apt.status === filter;
    return matchesSearch && matchesFilter;
  });

  const counts = {
    all: appointments.length,
    pending: appointments.filter((a) => a.status === "pending").length,
    confirmed: appointments.filter((a) => a.status === "confirmed").length,
    cancelled: appointments.filter((a) => a.status === "cancelled").length,
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-8 flex items-center justify-center bg-[#FAF8F4]">
        <div className="text-center">
          <div className="w-12 h-12 border-3 border-[#D4755B] border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-[#5A5856] font-medium">Loading appointments...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pt-8 pb-12 px-4 bg-[#FAF8F4]">
      <div className="max-w-7xl mx-auto">

        {/* Header */}
        <motion.div initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} className="mb-8">
          <h1 className="text-3xl font-bold text-[#1C1B1A] mb-1">Appointments</h1>
          <p className="text-[#5A5856]">Manage and track property viewing appointments</p>
        </motion.div>

        {/* Filter Tabs + Search */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
          className="bg-white rounded-2xl p-4 border border-[#E6D5C3] shadow-card mb-6">
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
            {/* Status Tabs */}
            <div className="flex items-center gap-1 bg-[#FAF8F4] rounded-xl p-1">
              {["all", "pending", "confirmed", "cancelled"].map((status) => (
                <button key={status} onClick={() => setFilter(status)}
                  className={cn(
                    "px-3 py-1.5 rounded-lg text-sm font-medium transition-all duration-200 capitalize",
                    filter === status
                      ? "bg-[#1C1B1A] text-[#FAF8F4] shadow-sm"
                      : "text-[#5A5856] hover:text-[#1C1B1A]"
                  )}>
                  {status === "all" ? "All" : status.charAt(0).toUpperCase() + status.slice(1)}
                  <span className={cn(
                    "ml-1.5 text-xs px-1.5 py-0.5 rounded-full",
                    filter === status ? "bg-white/20" : "bg-[#E6D5C3] text-[#5A5856]"
                  )}>
                    {counts[status]}
                  </span>
                </button>
              ))}
            </div>

            {/* Search */}
            <div className="relative w-full sm:w-72">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#9CA3AF]" />
              <input type="text" placeholder="Search by property, client..."
                value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2.5 bg-[#FAF8F4] border border-[#E6D5C3] rounded-xl text-sm text-[#1C1B1A] placeholder-[#9CA3AF] outline-none focus:border-[#D4755B] focus:ring-2 focus:ring-[#D4755B]/15 transition-all" />
            </div>
          </div>
        </motion.div>

        {/* Table */}
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}
          className="bg-white rounded-2xl border border-[#E6D5C3] shadow-card overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="bg-[#1C1B1A]">
                  {["Property", "Client", "Date & Time", "Status", "Meeting Link", "Actions"].map((h) => (
                    <th key={h} className="px-6 py-4 text-left text-xs font-semibold text-[#9CA3AF] uppercase tracking-wider">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-[#F5F1E8]">
                <AnimatePresence>
                  {filteredAppointments.map((appointment) => (
                    <motion.tr key={appointment._id}
                      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                      className="hover:bg-[#FAF8F4] transition-colors duration-150">

                      {/* Property */}
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2.5">
                          <div className="w-8 h-8 bg-[#D4755B]/10 rounded-lg flex items-center justify-center flex-shrink-0">
                            <Home className="w-4 h-4 text-[#D4755B]" />
                          </div>
                          <div>
                            <p className="text-sm font-semibold text-[#1C1B1A] line-clamp-1">
                              {appointment.propertyId.title}
                            </p>
                            <p className="text-xs text-[#9CA3AF]">{appointment.propertyId.location}</p>
                          </div>
                        </div>
                      </td>

                      {/* Client */}
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2.5">
                          <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0", appointment.userId ? "bg-blue-50" : "bg-amber-50")}>
                            <User className={cn("w-4 h-4", appointment.userId ? "text-blue-500" : "text-amber-500")} />
                          </div>
                          <div>
                            <p className="text-sm font-semibold text-[#1C1B1A]">
                              {appointment.userId?.name || appointment.guestInfo?.name || "Unknown"}
                            </p>
                            <p className="text-xs text-[#9CA3AF]">
                              {appointment.userId?.email || appointment.guestInfo?.email || "—"}
                            </p>
                            {!appointment.userId && appointment.guestInfo && (
                              <span className="text-[10px] px-1.5 py-0.5 bg-amber-50 text-amber-600 border border-amber-200 rounded-full font-medium">Guest</span>
                            )}
                          </div>
                        </div>
                      </td>

                      {/* Date & Time */}
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <Calendar className="w-4 h-4 text-[#9CA3AF] flex-shrink-0" />
                          <div>
                            <p className="text-sm font-medium text-[#1C1B1A]">
                              {formatDate(appointment.date)}
                            </p>
                            <div className="flex items-center gap-1 text-xs text-[#9CA3AF]">
                              <Clock className="w-3 h-3" />
                              {appointment.time}
                            </div>
                          </div>
                        </div>
                      </td>

                      {/* Status */}
                      <td className="px-6 py-4">
                        <StatusBadge status={appointment.status} />
                      </td>

                      {/* Meeting Link */}
                      <td className="px-6 py-4">
                        {editingMeetingLink === appointment._id ? (
                          <div className="flex items-center gap-1.5">
                            <input type="url" value={meetingLink}
                              onChange={(e) => setMeetingLink(e.target.value)}
                              placeholder="Paste meeting link..."
                              className="px-2.5 py-1.5 border border-[#E6D5C3] rounded-lg text-xs w-40 outline-none focus:border-[#D4755B] focus:ring-1 focus:ring-[#D4755B]/20" />
                            <button onClick={() => handleMeetingLinkUpdate(appointment._id)}
                              className="p-1.5 bg-[#D4755B] text-white rounded-lg hover:bg-[#C05E44] transition-colors">
                              <Send className="w-3.5 h-3.5" />
                            </button>
                            <button onClick={() => { setEditingMeetingLink(null); setMeetingLink(""); }}
                              className="p-1.5 bg-[#E6D5C3] text-[#5A5856] rounded-lg hover:bg-[#D4B99A] transition-colors">
                              <X className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        ) : (
                          <div className="flex items-center gap-2">
                            {appointment.meetingLink ? (
                              <a href={appointment.meetingLink} target="_blank" rel="noopener noreferrer"
                                className="flex items-center gap-1 text-xs text-[#D4755B] hover:text-[#C05E44] font-medium underline underline-offset-2">
                                <LinkIcon className="w-3.5 h-3.5" />
                                View Link
                              </a>
                            ) : (
                              <span className="text-xs text-[#9CA3AF]">No link</span>
                            )}
                            {appointment.status === "confirmed" && (
                              <button onClick={() => { setEditingMeetingLink(appointment._id); setMeetingLink(appointment.meetingLink || ""); }}
                                className="p-1 text-[#9CA3AF] hover:text-[#D4755B] transition-colors rounded">
                                <LinkIcon className="w-3.5 h-3.5" />
                              </button>
                            )}
                          </div>
                        )}
                      </td>

                      {/* Actions */}
                      <td className="px-6 py-4">
                        {appointment.status === "pending" && (
                          <div className="flex items-center gap-1.5">
                            {updatingId === appointment._id ? (
                              <Loader2 className="w-4 h-4 text-[#9CA3AF] animate-spin" />
                            ) : (
                              <>
                                <button
                                  onClick={() => handleStatusChange(appointment._id, "confirmed")}
                                  className="flex items-center gap-1 px-2.5 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-xs font-medium hover:bg-emerald-100 transition-colors">
                                  <Check className="w-3.5 h-3.5" />
                                  Confirm
                                </button>
                                <button
                                  onClick={() => handleStatusChange(appointment._id, "cancelled")}
                                  className="flex items-center gap-1 px-2.5 py-1.5 bg-red-50 text-red-700 border border-red-200 rounded-lg text-xs font-medium hover:bg-red-100 transition-colors">
                                  <X className="w-3.5 h-3.5" />
                                  Cancel
                                </button>
                              </>
                            )}
                          </div>
                        )}
                      </td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          </div>

          {filteredAppointments.length === 0 && (
            <div className="text-center py-16">
              <div className="w-14 h-14 bg-[#F5F1E8] rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Calendar className="w-7 h-7 text-[#E6D5C3]" />
              </div>
              <h3 className="text-base font-semibold text-[#1C1B1A] mb-1">No appointments found</h3>
              <p className="text-sm text-[#9CA3AF]">
                {searchTerm || filter !== "all" ? "Try adjusting your search or filters" : "No appointments have been scheduled yet"}
              </p>
            </div>
          )}
        </motion.div>
      </div>
    </div>
  );
};

export default Appointments;

import { useState, useEffect, useCallback } from "react";
