const parseAmenities = (amenities) => {
  if (!amenities || !Array.isArray(amenities)) return [];
  try {
    return typeof amenities[0] === "string"
      ? JSON.parse(amenities[0].replace(/'/g, '"'))
      : amenities;
  } catch {
    return [];
  }
};

