          {/* Tab Content */}
          <div className="p-6">
            {activeTab === 'overview' && (
              <div className="space-y-6">
                <h3 className="text-lg font-bold text-[#1C1B1A]">Account Overview</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
